CREATE TABLE enterprise_pricing_catalog (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, tenant_id UUID, catalog_code TEXT NOT NULL, catalog_name TEXT NOT NULL, currency TEXT DEFAULT 'USD', status TEXT DEFAULT 'ACTIVE', provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_price_books (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, catalog_id UUID, book_name TEXT NOT NULL, region TEXT DEFAULT 'GLOBAL', effective_from DATE NOT NULL, effective_to DATE, is_default BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_models (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, model_code TEXT NOT NULL, model_type TEXT DEFAULT 'SUBSCRIPTION_TIERED', billing_frequency TEXT DEFAULT 'ANNUAL', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_tiers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, model_id UUID, tier_name TEXT NOT NULL, base_price_usd NUMERIC(12,2) DEFAULT 1200.00, included_units INTEGER DEFAULT 100, overage_rate_usd NUMERIC(8,2) DEFAULT 15.00, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_discounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, discount_code TEXT NOT NULL, discount_pct NUMERIC(5,2) DEFAULT 15.00, approval_tier TEXT DEFAULT 'VP_SALES', status TEXT DEFAULT 'ACTIVE', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_promotions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, promo_name TEXT NOT NULL, discount_override_pct NUMERIC(5,2) DEFAULT 20.00, start_date DATE NOT NULL, end_date DATE NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_packages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, package_name TEXT NOT NULL, bundle_discount_pct NUMERIC(5,2) DEFAULT 12.50, is_custom BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_monetization (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, stream_name TEXT NOT NULL, stream_type TEXT DEFAULT 'RECURRING_SUBSCRIPTION', annual_run_rate_usd NUMERIC(14,2) DEFAULT 24500000.00, margin_pct NUMERIC(5,2) DEFAULT 78.5, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_price_realization (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, deal_id TEXT NOT NULL, list_price_usd NUMERIC(12,2) DEFAULT 50000.00, contracted_price_usd NUMERIC(12,2) DEFAULT 42500.00, realized_price_usd NUMERIC(12,2) DEFAULT 42500.00, realization_rate_pct NUMERIC(5,2) DEFAULT 85.0, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_price_elasticity (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, product_segment TEXT NOT NULL, elasticity_coefficient NUMERIC(5,2) DEFAULT -1.25, confidence_score NUMERIC(5,2) DEFAULT 87.5, status TEXT DEFAULT 'ESTIMATED', analyzed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_willingness_to_pay (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, customer_segment TEXT NOT NULL, estimated_wtp_usd NUMERIC(12,2) DEFAULT 65000.00, uncertainty_pct NUMERIC(5,2) DEFAULT 12.0, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_anomalies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, anomaly_type TEXT NOT NULL, deviation_pct NUMERIC(5,2) DEFAULT 38.5, status TEXT DEFAULT 'INVESTIGATING', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_revenue_risks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, risk_title TEXT NOT NULL, revenue_at_risk_usd NUMERIC(14,2) DEFAULT 850000.00, severity TEXT DEFAULT 'HIGH', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, scenario_name TEXT NOT NULL, price_delta_pct NUMERIC(5,2) DEFAULT 8.0, simulated_arr_delta_usd NUMERIC(14,2) DEFAULT 1450000.00, status TEXT DEFAULT 'SIMULATED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, forecast_horizon TEXT DEFAULT '12_MONTHS', projected_gross_margin_pct NUMERIC(5,2) DEFAULT 81.2, status TEXT DEFAULT 'FORECAST', confidence_score NUMERIC(5,2) DEFAULT 88.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_values (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, projected_value_usd NUMERIC(14,2) NOT NULL, realized_value_usd NUMERIC(14,2) DEFAULT 0.00, variance_usd NUMERIC(14,2) DEFAULT 0.00, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_drift (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, entity_id UUID NOT NULL, drift_type TEXT NOT NULL, drift_level TEXT DEFAULT 'NO_DRIFT', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_learning (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, event_type TEXT NOT NULL, description TEXT NOT NULL, append_only BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_recommendations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, recommendation_type TEXT NOT NULL, title TEXT NOT NULL, rationale TEXT NOT NULL, confidence_score NUMERIC(5,2) DEFAULT 89.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_traces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, root_signal_id TEXT NOT NULL, trace_payload JSONB DEFAULT '{}'::jsonb, provenance_hash TEXT NOT NULL, generated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_entitlements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, tier_id UUID, entitlement_key TEXT NOT NULL, quota_limit INTEGER DEFAULT 1000, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_competitors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, competitor_name TEXT NOT NULL, estimated_price_usd NUMERIC(12,2) DEFAULT 48000.00, positioning TEXT DEFAULT 'PREMIUM', observed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, customer_id TEXT NOT NULL, price_floor_usd NUMERIC(12,2) DEFAULT 35000.00, indexation_cap_pct NUMERIC(5,2) DEFAULT 5.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, request_id TEXT NOT NULL, approver_role TEXT NOT NULL, status TEXT DEFAULT 'APPROVED', approved_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_leakage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, leakage_type TEXT DEFAULT 'OFF_BOOK_DISCOUNT', annual_leakage_usd NUMERIC(14,2) DEFAULT 320000.00, detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE enterprise_pricing_experiments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, experiment_name TEXT NOT NULL, sample_size INTEGER DEFAULT 250, conversion_delta_pct NUMERIC(5,2) DEFAULT 4.2, status TEXT DEFAULT 'COMPLETED', created_at TIMESTAMPTZ DEFAULT NOW());
